<template>
  <section id="agent-conversation" class="conversation-room" :class="{compact,'messages-only':!showMap}" aria-label="Agent conversation view">
    <header class="room-heading"><div><h2>{{ !showMap?'Agent conversation':compact?'Agent graph':'Watch the agents.' }}</h2><p v-if="!compact">{{ showMap?'See each agent arrive and exchange views. Drag to arrange them; click to read their conversation.':'Choose an agent to inspect its actual saved conversation.' }}</p></div><span class="room-mode" :class="{live:following}">{{ replaying?'Replay of saved messages':following?'Following saved updates':'Browsing saved messages' }}</span></header>
    <div class="room-toolbar">
      <div class="room-lenses" role="group" aria-label="Conversation group"><button :aria-pressed="lens==='specialists'" @click="chooseLens('specialists')">Specialists <span>{{ specialistCount }}</span></button><button :aria-pressed="lens==='traders'" @click="chooseLens('traders')">Traders <span>{{ traderCount||'—' }}</span></button></div>
      <div class="playback-buttons"><button v-if="run.status==='running'&&!replaying" @click="toggleFollowing">{{ following?'Pause following':'Follow live' }}</button><button v-if="!replaying" :disabled="!events.length" @click="startReplay">Replay saved discussion</button><template v-else><button @click="playing=!playing" :disabled="!events.length">{{ playing?'Pause replay':'Play replay' }}</button><button @click="backToLatest">Back to latest</button><label>Speed<select v-model.number="speed" aria-label="Replay speed"><option :value="1">1×</option><option :value="2">2×</option><option :value="4">4×</option></select></label></template></div>
    </div>
    <p class="room-status" role="status">{{ registeredCount }} {{ lens==='specialists'?'specialist roles':'trader identities' }} {{ replaying?'shown in this replay':'registered' }}<span> · {{ events.length }} saved messages</span><span v-if="replaying"> · Message {{ cursor }} / {{ events.length }}</span></p>
    <p v-if="replaying" class="replay-note">Replaying the saved discussion, not running new agents. <template v-if="showMap">Nodes appear with their first shown message; </template>playback follows discussion order, not elapsed time.</p>
    <p v-else-if="run.reassessed_from_run_id||run.resumed_from_run_id" class="replay-note">This run reuses earlier messages. The original recording dates are shown below.</p>
    <label v-if="!showMap" class="agent-finder message-agent-finder">Find an agent<select :value="actorId" @change="chooseAgent($event.target.value)" aria-label="Find an agent in the conversation"><option value="">Choose an agent</option><option v-for="node in agentNodes" :key="node.id" :value="node.id">{{ node.label }}</option></select></label>
    <div class="room-layout">
      <div v-if="showMap" class="room-map">
        <div class="map-title"><button class="reset-layout" @click="resetPositions">Reset positions</button><span>{{ replaying?'Saved conversation replay':following?'Latest saved exchange':'Conversation map' }}</span><span>{{ current?.kind==='opening'?'Opening view':current?kindLabel(current.kind):'Waiting for messages' }}</span></div>
        <div ref="sceneViewport" class="scene-scroll" tabindex="0" aria-label="Agent conversation map">
          <svg class="conversation-scene" :viewBox="compact?'0 0 920 430':'0 0 920 650'" role="group" :aria-label="`${lens==='traders'?'Trader':'Specialist'} conversation nodes`">
            <defs><marker :id="markerId" viewBox="0 0 10 10" refX="10" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0L10 5L0 10Z" fill="#ff4f00"/></marker></defs>
            <g v-for="edge in activeEdges" :key="edge.id" class="scene-connection"><path :d="edge.path" class="conversation-wire" :marker-end="`url(#${markerId})`"/><circle v-if="!reducedMotion&&(playing||following&&freshEvents.has(current?.id))" :key="`${current?.id}-${edge.id}`" r="5" fill="#ff4f00"><animateMotion :path="edge.path" dur="1.1s" repeatCount="1" fill="freeze"/></circle></g>
            <g v-if="compact" class="saved-network-wires"><path v-for="edge in graph.edges" :key="edge.id" :d="edge.path"/></g>
            <TransitionGroup tag="g" name="agent-arrival">
              <g v-for="(node,index) in graph.nodes" :key="node.id" :transform="`translate(${node.x},${node.y})`" :class="['scene-node',{'scene-agent':isAgent(node),newcomer:replaying||freshAgents.has(`${lens}:${node.id}`),involved:involved.has(node.id),quiet:current&&!involved.has(node.id),pinned:actorId===node.id,dragging:dragging===node.id}]" :style="{'--arrival-delay':`${Math.min(index%14,10)*24}ms`}" :role="isAgent(node)?'button':undefined" :tabindex="isAgent(node)?0:undefined" :data-agent-id="isAgent(node)?node.id:undefined" :aria-pressed="isAgent(node)?actorId===node.id:undefined" :aria-label="isAgent(node)?`${node.label} · ${node.status}`:node.label" @click="isAgent(node)&&activate($event,node,chooseAgent)" @pointerdown="isAgent(node)&&startDrag($event,node)" @touchstart.prevent @pointermove="moveDrag" @pointerup="finishDrag($event,false,chooseAgent)" @pointercancel="finishDrag($event,true)" @lostpointercapture="finishDrag($event,true)" @keydown="isAgent(node)&&nudge($event,node)" @keydown.enter.prevent="isAgent(node)&&chooseAgent(node.id)" @keydown.space.prevent="isAgent(node)&&chooseAgent(node.id)">
                <title>{{ node.label }} · {{ node.status||'Recorded group' }}</title>
                <circle v-if="isAgent(node)" :r="radius(node)+7" fill="transparent"/>
                <g class="node-core"><circle v-if="involved.has(node.id)" :key="`${current?.id}-${node.id}`" class="speaker-halo" :r="radius(node)+7"/><circle class="agent-avatar" :r="radius(node)" :fill="nodeColor(node)"/><text v-if="node.type!=='trader'||readableTraders" class="avatar-initial" text-anchor="middle" y="4">{{ compact?node.displayNumber:node.type==='trader'?node.number:initials(node) }}</text></g>
                <text v-if="!compact&&node.type!=='trader'" class="scene-label" :class="{'analyst-label':node.type==='analyst'}" text-anchor="middle"><tspan v-for="(line,i) in lines(node)" :key="i" x="0" :y="radius(node)+19+i*17">{{ line }}</tspan></text>
                <text v-else-if="!compact&&(readableTraders||involved.has(node.id)||actorId===node.id)" class="scene-label trader-label" text-anchor="middle" :y="readableTraders?radius(node)+19:-17">{{ readableTraders?`Trader ${String(node.number).padStart(2,'0')}`:node.label }}</text>
              </g>
            </TransitionGroup>
          </svg>
        </div>
        <p class="mobile-map-hint">Drag a node to move it. Swipe the background to explore.</p>
        <div class="map-legend"><span><i class="legend-dot speaker"></i>Speaker / recipient</span><span v-if="compact"><i class="legend-dot bullish-view"></i>Bullish</span><span v-if="compact"><i class="legend-dot bearish-view"></i>Bearish</span><span><i class="legend-dot waiting"></i>{{ compact?'Mixed / waiting':'Waiting for a saved view' }}</span><span>Click to inspect · drag or use arrow keys to move</span></div>
        <label class="agent-finder">Find an agent<select :value="actorId" @change="chooseAgent($event.target.value)" aria-label="Find an agent in the conversation"><option value="">Choose an agent</option><option v-for="node in agentNodes" :key="node.id" :value="node.id">{{ node.label }}</option></select></label>
      </div>
      <aside class="spoken-exchange" aria-label="Selected agent conversation" @pointerdown="pause" @focusin="pause" @wheel.passive="pause">
        <div v-if="selectedAgent" class="agent-details">
          <p class="exchange-kind">{{ selectedAgent.type==='trader'?`Trader ${String(selectedAgent.number).padStart(2,'0')}`:'Selected specialist' }}</p>
          <h3>{{ selectedAgent.label }}</h3><p>{{ selectedAgent.status }}</p>
          <p v-if="selectedAgent.trader">{{ selectedStyle }}</p>
          <p v-else>{{ selectedAgent.role?.focus }}</p>
          <details v-if="selectedAgent.type==='trader'"><summary>Read this trader's saved conversation</summary><TraderMemory :dialogue="projected.trader_dialogue" :review="!replaying||cursor===events.length?run.trader_review:null" :levels="run.observation?.levels||[]" :actor-id="selectedAgent.id" @inspect="chooseAgent" /></details>
        </div>
        <template v-if="current">
          <p class="exchange-kind">{{ kindLabel(current.kind) }}<time v-if="current.at"> · {{ recordedTime(current.at) }}</time></p>
          <h3>{{ name(current.author) }}<span v-if="current.recipients.length"> to {{ current.recipients.map(name).join(', ') }}</span></h3>
          <div class="speech-bubble current-bubble"><strong>{{ name(current.author) }} · {{ kindLabel(current.kind) }}</strong><p>{{ current.text }}</p></div>
          <template v-if="context.length===1"><div class="speech-bubble context-bubble"><strong>{{ name(context[0].author) }} · {{ context[0].kind }}</strong><p>{{ context[0].text }}</p></div></template>
          <details v-else-if="context.length>1" class="peer-context"><summary>Read the {{ context.length }} peer views behind this response</summary><div v-for="item in context" :key="item.author" class="speech-bubble context-bubble"><strong>{{ name(item.author) }} · {{ item.kind }}</strong><p>{{ item.text }}</p></div></details>
          <details v-if="current.message.change_reason||current.message.revised_thesis" class="decision-change"><summary>What changed after this exchange?</summary><p>{{ current.message.change_reason }}</p><p v-if="current.message.revised_thesis">{{ current.message.revised_thesis }}</p></details>
        </template>
        <div v-else class="exchange-empty"><span class="empty-speaker" aria-hidden="true"></span><h3>{{ actorId?name(actorId):replaying?'Meet the agents as their messages appear':'Waiting for the first saved exchange' }}</h3><p>{{ actorId?'No message involving this agent has been shown yet.':replaying?'Play the saved discussion or step forward one message.':showMap?'Registered roles appear on the map. A question lights up its sender and recipient; the saved reply appears here when it arrives.':'Choose an agent to inspect its saved exchanges. Messages appear here only when recorded.' }}</p></div>
      </aside>
    </div>
    <div v-if="events.length&&(!compact||replaying)" class="conversation-timeline"><div class="timeline-controls"><button :disabled="position<=1" @click="step(-1)">Previous message</button><label>Jump to a round<select :value="current?.phase||''" @change="jumpRound($event.target.value)" aria-label="Conversation round"><option value="" disabled>Choose round</option><option v-for="phase in availablePhases" :key="phase" :value="phase">{{ phaseLabel(phase) }}</option></select></label><button :disabled="position>=events.length" @click="step(1)">Next message</button></div><input type="range" :min="0" :max="events.length" :value="position" @input="seek(Number($event.target.value))" aria-label="Saved conversation position"><p>{{ replaying?`Message ${cursor} of ${events.length} · replay controls affect this view only.`:'The map highlights saved messages as they arrive. Select an agent to pause following and read its exchange.' }}</p></div>
    <p class="room-footnote">{{ compact?'These identities share the connected model and captured evidence. Each displayed exchange was saved by the discussion engine.':'Each animation corresponds to a saved message or newly registered identity. Updates arrive in batches; agent identities share the same model and chart evidence.' }}</p>
  </section>
</template>

<script setup>
import {computed,nextTick,onBeforeUnmount,onMounted,ref,shallowRef,toRaw,useId,watch} from 'vue'
import {useGraphDrag} from '../utils/useGraphDrag.js'
import {spreadNodes} from '../utils/presentationGraphs.mjs'
import {routeGraphEdges} from '../utils/agentGraph.mjs'
import TraderMemory from './TraderMemory.vue'
import {conversationEvents,projectConversation,conversationGraph,conversationContext,automaticConversationLens} from '../utils/conversationScene.mjs'
const props=defineProps({run:{type:Object,required:true},initialLens:{type:String,default:'auto'},compact:Boolean,showMap:{type:Boolean,default:true}})
const markerId=`conversation-arrow-${useId().replace(/[^a-zA-Z0-9_-]/g,'')}`
const sceneViewport=ref(null)
const initialLens=()=>['specialists','traders'].includes(props.initialLens)?props.initialLens:props.run.trader_dialogue?'traders':'specialists'
const manualLens=ref(initialLens()),following=ref(props.run.status==='running'),replaying=ref(false),playing=ref(false),speed=ref(1),cursor=ref(0),eventId=ref(''),actorId=ref(''),snapshot=shallowRef(null),reducedMotion=ref(false)
const source=computed(()=>replaying.value?snapshot.value:props.run)
const lens=computed(()=>!replaying.value&&following.value&&props.initialLens==='auto'?automaticConversationLens(props.run):manualLens.value)
const events=computed(()=>conversationEvents(source.value,lens.value))
const visibleEvents=computed(()=>replaying.value?events.value.slice(0,cursor.value):events.value)
const current=computed(()=>eventId.value?visibleEvents.value.find(event=>event.id===eventId.value)||null:actorId.value?null:visibleEvents.value.at(-1)||null)
const projected=computed(()=>replaying.value?projectConversation(source.value,lens.value,events.value,cursor.value):source.value)
const {positions,dragging,startDrag,moveDrag,finishDrag,activate,nudge,resetPositions}=useGraphDrag(computed(()=>`${props.run.id}:conversation:${lens.value}${props.compact?':workspace':''}`),pause)
const graph=computed(()=>{const saved=conversationGraph(projected.value,lens.value,source.value,current.value?.kind==='cross_reply'?'cross_group':'paired',positions.value);if(!props.compact)return saved;const full=conversationGraph(source.value,lens.value,source.value,current.value?.kind==='cross_reply'?'cross_group':'paired'),anchors=new Map(spreadNodes(full.nodes.filter(node=>['analyst','trader'].includes(node.type)),positions.value).map(n=>[n.id,n]));const nodes=saved.nodes.filter(n=>anchors.has(n.id)).map(n=>({...n,...anchors.get(n.id)})),known=new Set(nodes.map(n=>n.id));return routeGraphEdges({nodes,edges:saved.edges.filter(e=>known.has(e.source)&&known.has(e.target))})})
const selectedAgent=computed(()=>graph.value.nodes.find(node=>node.id===actorId.value))
const selectedStyle=computed(()=>projected.value.trader_dialogue?.cohorts?.find(group=>group.id===selectedAgent.value?.trader?.behavior)?.behavior||'')
const readableTraders=computed(()=>(source.value.trader_dialogue?.participants?.length||0)<=60)
const activeEdges=computed(()=>graph.value.edges.filter(edge=>current.value?.edgeIds.includes(edge.id)))
const involved=computed(()=>new Set(current.value?[current.value.author,...current.value.recipients]:actorId.value?[actorId.value]:[]))
const context=computed(()=>conversationContext(projected.value,lens.value,current.value))
const isAgent=node=>['analyst','trader'].includes(node.type)
const agentNodes=computed(()=>graph.value.nodes.filter(isAgent)),registeredCount=computed(()=>agentNodes.value.length)
const specialistCount=computed(()=>props.run.roster?.filter(role=>role.active).length||0),traderCount=computed(()=>props.run.trader_dialogue?.participants?.length||0)
const position=computed(()=>replaying.value?cursor.value:current.value?events.value.findIndex(event=>event.id===current.value.id)+1:0)
const availablePhases=computed(()=>[...new Set(events.value.map(event=>event.phase))])
const name=id=>graph.value.nodes.find(node=>node.id===id)?.label||props.run.roster?.find(role=>role.id===id)?.name||source.value.trader_dialogue?.participants?.find(person=>person.id===id)?.name||id
const kindLabel=kind=>({opening:'Opening view',question:'Question',reply:'Reply',cross_reply:'Response to peers'}[kind]||kind)
const phaseLabel=phase=>({opinions:'Opening views',openings:'Opening views',challenges:'Questions',questions:'Questions',replies:'Replies',cross_group_replies:'Across trading styles'}[phase]||phase)
const recordedTime=value=>new Date(value).toLocaleString(undefined,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})
const radius=node=>props.compact?(readableTraders.value?13:6):node.type==='trader'?(readableTraders.value?18:6):21
const initials=node=>node.type==='input'?'C':node.type==='moderator'?'M':node.type==='simulation'?'V':node.label.split(/[ &/-]+/).filter(Boolean).slice(0,2).map(word=>word[0]).join('').toUpperCase()
const shortLabels={ict_liquidity:['ICT liquidity'],ict_fvg:['ICT gaps'],ict_orderblocks:['Order blocks'],support_resistance:['Support /','resistance'],price_action:['Price action'],trend:['Trend'],momentum:['Momentum'],mean_reversion:['Mean reversion'],overextension:['Overextension','& pullbacks'],potential_top:['Potential top'],potential_bottom:['Potential bottom'],volume:['Volume / auction'],classical:['Patterns'],risk:['Risk review']}
const lines=node=>{if(shortLabels[node.id])return shortLabels[node.id];const label=node.type==='cohort'?node.label:node.label.replace(/ trader$/,'').replace(' & skeptic','');const words=label.split(' '),first=[],last=[];for(const word of words)((first.join(' ').length+word.length<20&&!last.length)?first:last).push(word);return [first.join(' '),last.join(' ')].filter(Boolean)}
const nodeColor=node=>involved.value.has(node.id)?'#ff4f00':props.compact?({bullish:'#568d77',bearish:'#b47567',pending:'#aab4c0'}[node.stance]||'#8291a2'):node.type==='input'||node.type==='moderator'?'#596371':node.type==='cohort'?'#737f8e':node.stance==='pending'?'#b4bbc5':'#4c5666'
let timer,motionQuery
const identities=run=>[...(run.roster||[]).filter(role=>role.active).map(role=>`specialists:${role.id}`),...(run.trader_dialogue?.participants||[]).map(person=>`traders:${person.id}`)]
const eventKeys=run=>['specialists','traders'].flatMap(group=>conversationEvents(run,group).map(event=>event.id))
let seenAgents=new Set(identities(props.run)),seenEvents=new Set(eventKeys(props.run))
const freshAgents=shallowRef(new Set()),freshEvents=shallowRef(new Set())
function pause(){const chosen=lens.value,id=current.value?.id;manualLens.value=chosen;following.value=false;playing.value=false;if(id)eventId.value=id}
function chooseLens(value){stopReplay();following.value=false;manualLens.value=value;actorId.value='';eventId.value=events.value.at(-1)?.id||''}
function chooseAgent(id){pause();actorId.value=id;const latest=[...visibleEvents.value].reverse();eventId.value=(latest.find(event=>event.author===id)||latest.find(event=>event.recipients.includes(id)))?.id||''}
function stopReplay(){playing.value=false;replaying.value=false;snapshot.value=null;cursor.value=0}
function backToLatest(){stopReplay();eventId.value='';actorId.value='';following.value=props.run.status==='running'}
function toggleFollowing(){if(following.value){manualLens.value=lens.value;following.value=false;eventId.value=current.value?.id||''}else{actorId.value='';eventId.value='';following.value=true}}
function prepareReplay(){const chosen=lens.value;pause();manualLens.value=chosen;snapshot.value=structuredClone(toRaw(props.run));replaying.value=true;eventId.value='';actorId.value=''}
function startReplay(){prepareReplay();cursor.value=0;playing.value=!reducedMotion.value}
function seek(value){if(!replaying.value)prepareReplay();playing.value=false;eventId.value='';actorId.value='';cursor.value=Math.max(0,Math.min(events.value.length,value))}
function step(delta){seek(position.value+delta)}
function jumpRound(phase){const index=events.value.findIndex(event=>event.phase===phase);if(index>=0)seek(index+1)}
watch([playing,speed,replaying],()=>{clearInterval(timer);if(playing.value&&replaying.value)timer=setInterval(()=>{eventId.value='';actorId.value='';if(cursor.value<events.value.length)cursor.value++;else playing.value=false},1400/speed.value)})
watch(()=>props.run.id,()=>{stopReplay();manualLens.value=initialLens();following.value=props.run.status==='running';eventId.value='';actorId.value='';seenAgents=new Set(identities(props.run));seenEvents=new Set(eventKeys(props.run));freshAgents.value=new Set();freshEvents.value=new Set()})
watch(()=>props.run.status,(status,previous)=>{if(status==='running'&&previous==='queued')following.value=true;if(status!=='running'){manualLens.value=lens.value;eventId.value=current.value?.id||'';following.value=false}})
watch(()=>props.run,run=>{const people=identities(run),messages=eventKeys(run);freshAgents.value=new Set(people.filter(id=>!seenAgents.has(id)));freshEvents.value=new Set(messages.filter(id=>!seenEvents.has(id)));people.forEach(id=>seenAgents.add(id));messages.forEach(id=>seenEvents.add(id));if(following.value&&!replaying.value){eventId.value='';actorId.value=''}})
function motionChanged(event){reducedMotion.value=event.matches;if(event.matches)playing.value=false}
function centerExchange(){if(dragging.value||actorId.value)return;const viewport=sceneViewport.value,svg=viewport?.querySelector('svg'),people=graph.value.nodes.filter(node=>involved.value.has(node.id));if(!viewport||!svg||!people.length)return;const x=people.reduce((sum,node)=>sum+node.x,0)/people.length,y=people.reduce((sum,node)=>sum+node.y,0)/people.length;viewport.scrollLeft=Math.max(0,x*svg.clientWidth/920-viewport.clientWidth/2);viewport.scrollTop=Math.max(0,y*svg.clientHeight/(props.compact?430:650)-viewport.clientHeight/2)}
watch(()=>current.value?.id,()=>nextTick(centerExchange))
onMounted(()=>{motionQuery=window.matchMedia('(prefers-reduced-motion: reduce)');reducedMotion.value=motionQuery.matches;motionQuery.addEventListener('change',motionChanged);window.addEventListener('resize',centerExchange);nextTick(centerExchange)})
onBeforeUnmount(()=>{clearInterval(timer);motionQuery?.removeEventListener('change',motionChanged);window.removeEventListener('resize',centerExchange)})
</script>

<style scoped>
.scene-agent *{touch-action:none}

.reset-layout{order:3;margin-left:auto;border:1px solid #d5d9df;border-radius:4px;padding:4px 8px;background:white;color:#49515d;font:inherit;cursor:pointer}.map-title{align-items:center;flex-wrap:wrap}.scene-agent{touch-action:none;user-select:none;cursor:grab!important}.scene-agent.dragging{cursor:grabbing!important;opacity:1!important}.agent-details{border-bottom:1px solid #e1e4e8;padding-bottom:15px;margin-bottom:20px}.agent-details h3{margin-bottom:6px}.agent-details>p{font-size:11px;line-height:1.7;color:#66717e}.agent-details summary{font-size:11px;cursor:pointer;color:#a33b10;margin-top:12px}.trader-label{fill:#49515d!important;font-weight:500!important}.conversation-room button:focus-visible,.conversation-room select:focus-visible{outline:2px solid #ff4f00;outline-offset:3px}

